"""Basketball units 1-5: offensive principles, ball-screen offense, defensive principles, ball-screen defence, and
zone, man and press. Two question types per objective.

These are tactical reads, so the first type is a described situation with the correct read, and the second is either
the geometry or the count behind it (how many defenders a spacing creates, what a coverage concedes in expected
points, how many passes a rotation needs) recomputed by the verifier. Terminology follows the USA Basketball
curriculum where it names a concept and common coaching usage otherwise.
"""
from opl_dsl import Q

FILE, FRAMEWORK, PRACTICE = "bb-core-2", "basketball", "P1"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
OF, PO, DF, PD, ZP = ("bb.offense", "bb.pnr-offense", "bb.defense", "bb.pnr-defense", "bb.zone-press")


def facts(name, skill, rows, explain):
    return Q(name, skill, "{{q}}", pace="recall",
             cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


